const WALKABLE_BYTES = Uint8Array.from(globalThis.atob(WALKABLE_BITS_BASE64), (value) => value.charCodeAt(0))

export function isMaskCellWalkable(column, row) {
  if (!Number.isInteger(column) || !Number.isInteger(row) || column < 0 || row < 0 || column >= WALKABLE_MASK_METADATA.width || row >= WALKABLE_MASK_METADATA.height) return false
  const index = row * WALKABLE_MASK_METADATA.width + column
  return Boolean(WALKABLE_BYTES[index >> 3] & (1 << (7 - (index & 7))))
}

export function isMaskPointWalkable(worldX, worldY, currentWorldWidth = WALKABLE_MASK_METADATA.baseWorldWidth, currentWorldHeight = WALKABLE_MASK_METADATA.baseWorldHeight) {
  const transform = createWorldTransform({ baseWorldWidth: WALKABLE_MASK_METADATA.baseWorldWidth, baseWorldHeight: WALKABLE_MASK_METADATA.baseWorldHeight, currentWorldWidth, currentWorldHeight })
  const cell = worldPointToMaskCell(worldX, worldY, transform, WALKABLE_MASK_METADATA.width, WALKABLE_MASK_METADATA.height)
  return cell ? isMaskCellWalkable(cell.column, cell.row) : false
}
